# ──────────────────────────────────────────────────────────────────────────
# DATACLASS
# ──────────────────────────────────────────────────────────────────────────

@dataclass
class RetrievedChunk:
    text: str
    document_number: str
    document_title: str
    article: Optional[str]


# ──────────────────────────────────────────────────────────────────────────
# CHARGEMENT UNIQUE
# pipeline.py charge les ressources RAG et construit le graphe LangGraph
# dès son import — aucun rechargement nécessaire ici.
# ──────────────────────────────────────────────────────────────────────────


# ──────────────────────────────────────────────────────────────────────────
# PIPELINE
# ──────────────────────────────────────────────────────────────────────────

def run_pipeline(query, conversation_history=None):
    """Exécute le pipeline BCT et retourne la réponse ainsi que les sources
    citées, présentées de façon lisible pour un utilisateur métier."""

    result = ask_bct(query, conversation_history=conversation_history)

    chunks = []
    for source in result["sources"]:
        chunks.append(
            RetrievedChunk(
                text=source["extrait"],
                document_number=source["number"],
                document_title=source["type"],
                article=source["article"],
            )
        )

    return {
        "answer": result["final_answer"],
        "chunks": chunks,
    }


# ──────────────────────────────────────────────────────────────────────────
# AFFICHAGE
# ──────────────────────────────────────────────────────────────────────────

def render_search_step(placeholder, step_text: str, caption: str):
    """Affiche le cercle de recherche animé avec un libellé clair,
    compréhensible par un utilisateur non technique."""

    placeholder.markdown(
        f"""
        <div class="bct-search-box">
            <div class="bct-spinner"></div>
            <div class="bct-search-text">
                <div class="bct-search-step">{step_text}</div>
                <div class="bct-search-caption">{caption}</div>
            </div>
        </div>
        """,
        unsafe_allow_html=True
    )


def make_user_avatar(letter: str) -> str:
    """Avatar utilisateur : cercle navy/or avec l'initiale du nom."""

    svg = f"""<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'>
        <circle cx='32' cy='32' r='30' fill='#0B2545' stroke='#9C7A35' stroke-width='3'/>
        <text x='32' y='42' font-family='Georgia, serif' font-size='26'
              font-weight='700' fill='#F7F5F0' text-anchor='middle'>{letter}</text>
    </svg>"""
    encoded = base64.b64encode(svg.encode("utf-8")).decode("utf-8")
    return f"data:image/svg+xml;base64,{encoded}"


def make_assistant_avatar() -> str:
    """Avatar assistant : fronton institutionnel (colonnes + pediment),
    cercle or/navy, cohérent avec l'identité visuelle de la BCT."""

    svg = """<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'>
        <circle cx='32' cy='32' r='30' fill='#9C7A35'/>
        <circle cx='32' cy='32' r='30' fill='none' stroke='#0B2545' stroke-width='2'/>
        <polygon points='16,24 32,13 48,24' fill='#0B2545'/>
        <rect x='16' y='24' width='32' height='3' fill='#0B2545'/>
        <rect x='19' y='27' width='4' height='15' fill='#0B2545'/>
        <rect x='30' y='27' width='4' height='15' fill='#0B2545'/>
        <rect x='41' y='27' width='4' height='15' fill='#0B2545'/>
        <rect x='15' y='42' width='34' height='4' fill='#0B2545'/>
    </svg>"""
    encoded = base64.b64encode(svg.encode("utf-8")).decode("utf-8")
    return f"data:image/svg+xml;base64,{encoded}"


def render_bubble_header(is_user: bool, avatar_uri: str, label: str):
    """En-tête de la bulle : avatar + nom, orienté selon l'émetteur."""

    css_class = "bct-bubble-header bct-bubble-header-user" if is_user else "bct-bubble-header"
    st.markdown(
        f"""
        <div class="{css_class}">
            <img src="{avatar_uri}" class="bct-bubble-avatar"/>
            <span class="bct-bubble-name">{label}</span>
        </div>
        """,
        unsafe_allow_html=True
    )


def render_unavailable(placeholder):
    """Affiche un message professionnel et rassurant lorsque le pipeline
    échoue (ex : clés API indisponibles), sans jamais exposer la trace
    technique à l'utilisateur final."""

    placeholder.markdown(
        """
        <div class="bct-error-box">
            <div class="bct-error-icon">🕐</div>
            <div>
                <div class="bct-error-title">Service momentanément indisponible</div>
                <div class="bct-error-text">
                    Nous sommes désolés, l'assistant n'est pas disponible pour le moment.
                    Veuillez réessayer ultérieurement.
                </div>
            </div>
        </div>
        """,
        unsafe_allow_html=True
    )


def render_sources(chunks):
    """Affiche les sources sous forme de fiches de citation réglementaire."""

    if not chunks:
        return

    with st.expander(f"📄 {len(chunks)} source(s) citée(s)"):
        for chunk in chunks:
            article_line = f"Art. {chunk.article}" if chunk.article else "Référence non numérotée"

            st.markdown(
                f"""
                <div class="source-card">
                    <div class="source-ref">{chunk.document_title} n° {chunk.document_number}</div>
                    <div class="source-article">{article_line}</div>
                    <div class="source-text">{chunk.text}</div>
                </div>
                """,
                unsafe_allow_html=True
            )


def render_message_row(role: str, key: str, avatar_uri: str, label: str, content_fn):
    """Affiche un message façon messagerie : bulle à droite pour
    l'utilisateur, à gauche pour l'assistant, avec en-tête avatar + nom."""

    is_user = role == "user"

    if is_user:
        _, col = st.columns([1, 3])
    else:
        col, _ = st.columns([3, 1])

    with col:
        with st.container(key=f"bct{'u' if is_user else 'a'}-{key}"):
            render_bubble_header(is_user, avatar_uri, label)
            content_fn()

    return col


# ──────────────────────────────────────────────────────────────────────────
# SIDEBAR
# ──────────────────────────────────────────────────────────────────────────

with st.sidebar:

    st.markdown(
        f"""
        <div class="bct-sidebar-brand">
            <div class="bct-sidebar-crest">
                <img src="{LOGO_WHITE_DATA_URI}" alt="Emblème BCT"/>
            </div>
            <span class="bct-pillars">
                <span></span><span></span><span></span><span></span>
            </span>
        </div>
        """,
        unsafe_allow_html=True
    )

    st.markdown('<div class="bct-section-label">Utilisateur</div>', unsafe_allow_html=True)

    user_name = st.text_input(
        "Votre nom",
        value=st.session_state.get("user_name", ""),
        placeholder="Ex : Eya"
    )
    st.session_state.user_name = user_name

    st.markdown('<div class="bct-section-label">Affichage</div>', unsafe_allow_html=True)

    show_sources = st.toggle(
        "Afficher les sources citées",
        value=True
    )

    st.markdown('<div class="bct-section-label">Session</div>', unsafe_allow_html=True)

    if st.button(
        "Réinitialiser la conversation",
        use_container_width=True
    ):
        st.session_state.messages = []
        st.rerun()

    st.markdown(
        """
        <div class="bct-footer" style="border-top-color: rgba(255,255,255,0.15); color:#AEB6C4;">
        Réponses générées par intelligence artificielle à partir du corpus
        réglementaire officiel de la BCT. Ne constitue pas un avis juridique.
        </div>
        """,
        unsafe_allow_html=True
    )


# ──────────────────────────────────────────────────────────────────────────
# SESSION
# ──────────────────────────────────────────────────────────────────────────

if "messages" not in st.session_state:
    st.session_state.messages = []

user_initial = (st.session_state.get("user_name") or "U").strip()[:1].upper() or "U"
user_label = (st.session_state.get("user_name") or "Vous").strip() or "Vous"
USER_AVATAR = make_user_avatar(user_initial)
ASSISTANT_AVATAR = make_assistant_avatar()


# ──────────────────────────────────────────────────────────────────────────
# EN-TÊTE
# ──────────────────────────────────────────────────────────────────────────

st.markdown(
    f"""
    <div class="bct-masthead">
        <div class="bct-masthead-row">
            <div class="bct-masthead-left">
                <div class="bct-masthead-crest">
                    <img src="{LOGO_WHITE_DATA_URI}" alt="Emblème BCT"/>
                </div>
                <div class="bct-masthead-text">
                    <div class="bct-eyebrow">Banque Centrale de Tunisie</div>
                    <div class="bct-title">
                        Assistant Réglementaire des Changes
                        <span class="bct-pillars"><span></span><span></span><span></span><span></span></span>
                    </div>
                </div>
            </div>
            <div class="bct-masthead-meta">
                <div class="bct-masthead-meta-label">Réglementation des changes</div>
                <div class="bct-masthead-meta-value">1975 — 2024</div>
            </div>
        </div>
    </div>
    """,
    unsafe_allow_html=True
)


# ──────────────────────────────────────────────────────────────────────────
# HISTORIQUE — bulles alignées comme une conversation de messagerie
# ──────────────────────────────────────────────────────────────────────────

for i, msg in enumerate(st.session_state.messages):

    def _make_renderer(m):
        def _renderer():
            st.markdown(m["content"])
            if m["role"] == "assistant" and show_sources:
                render_sources(m.get("chunks"))
        return _renderer

    if msg["role"] == "user":
        render_message_row("user", str(i), USER_AVATAR, user_label, _make_renderer(msg))
    else:
        render_message_row("assistant", str(i), ASSISTANT_AVATAR, "Assistant BCT", _make_renderer(msg))


# ──────────────────────────────────────────────────────────────────────────
# QUESTION — champ de saisie + bouton flottant vers le corpus original
# ──────────────────────────────────────────────────────────────────────────

st.markdown(
    f"""
    <a href="{CORPUS_PDF_URL}" target="_blank" rel="noopener noreferrer"
       class="bct-corpus-fab" title="Consulter le corpus réglementaire original">
        <svg viewBox="0 0 24 24">
            <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
            <polyline points="14 2 14 8 20 8"/>
            <path d="M9 13h6"/>
            <path d="M9 17h6"/>
        </svg>
    </a>
    """,
    unsafe_allow_html=True
)

st.markdown('<div class="bct-input-wrap">', unsafe_allow_html=True)

question = st.chat_input(
    "Ex : Quelles sont les modalités de rapatriement des devises à l'export ?"
)

st.markdown('</div>', unsafe_allow_html=True)

if question:

    st.session_state.messages.append(
        {
            "role": "user",
            "content": question
        }
    )

    render_message_row("user", "live-q", USER_AVATAR, user_label, lambda: st.markdown(question))

    assistant_col, _ = st.columns([3, 1])

    with assistant_col:
        with st.container(key="bcta-live-a"):

            render_bubble_header(False, ASSISTANT_AVATAR, "Assistant BCT")

            placeholder = st.empty()

            # Étapes visuelles du cercle de recherche : donnent à l'utilisateur
            # un retour clair et rassurant pendant le traitement, sans jargon
            # technique (pas d'agents, d'intent, de retries...).
            render_search_step(
                placeholder,
                "Analyse de votre question…",
                "Compréhension du sujet réglementaire"
            )
            time.sleep(0.6)

            render_search_step(
                placeholder,
                "Recherche dans la réglementation des changes…",
                "Consultation du corpus officiel BCT (1975–2024)"
            )

            history_for_context = [
                {"role": m["role"], "content": m["content"]}
                for m in st.session_state.messages[:-1]
            ]

            pipeline_failed = False

            try:
                result = run_pipeline(
                    query=question,
                    conversation_history=history_for_context
                )
            except Exception as e:
                # La trace technique complète (ex: RuntimeError clés Gemini/Groq
                # indisponibles) est journalisée côté serveur pour le
                # développeur, mais jamais affichée à l'utilisateur final.
                print(f"[BCT Assistant] Erreur pipeline : {e}")
                pipeline_failed = True
                result = {"answer": None, "chunks": []}

            if pipeline_failed:
                render_unavailable(placeholder)
            else:
                render_search_step(
                    placeholder,
                    "Rédaction de la réponse…",
                    "Vérification de la cohérence avec les textes cités"
                )
                time.sleep(0.4)

                placeholder.markdown(result["answer"])

                if show_sources:
                    render_sources(result["chunks"])

    if pipeline_failed:
        st.session_state.messages.append(
            {
                "role": "assistant",
                "content": (
                    "Nous sommes désolés, l'assistant n'est pas disponible "
                    "pour le moment. Veuillez réessayer ultérieurement."
                ),
                "chunks": [],
            }
        )
    else:
        st.session_state.messages.append(
            {
                "role": "assistant",
                "content": result["answer"],
                "chunks": result["chunks"],
            }
        )


# ──────────────────────────────────────────────────────────────────────────
